test('every bundled Leventhal record carries its primary rights evidence without relabelling', () => {
  const bpl = records.filter((record) => record.providerId === 'leventhal');
  assert.equal(bpl.length, 10242, 'the complete admitted BPL scope stays bundled');
  const ccBy = bpl.filter((record) => record.rightsBasis === 'cc-by');
  assert.equal(ccBy.length, 11);
  for (const record of bpl) {
    assert.equal(record.rightsStatement, record.rights.replace(record.licenseStatement ?? '', '').trim(), `${record.id}: the verbatim rights statement is preserved`);
    assert.ok(record.licenseStatement, `${record.id}: the licence statement is preserved`);
    assert.equal(record.rightsPolicyUrl, 'https://www.digitalcommonwealth.org/copyright');
    assert.match(record.metadataSource, /^https:\/\/collections\.leventhalmap\.org\/search\/commonwealth:[a-z0-9]+\.json$/);
    if (record.rightsBasis !== 'cc-by') {
      assert.equal(record.rightsUrl, undefined, `${record.id}: a no-known-copyright record must not gain an invented licence URI`);
    }
  }
  for (const record of ccBy) {
    assert.equal(record.rightsUrl, 'https://creativecommons.org/licenses/by/4.0/', `${record.id}: the item's stated licence URI`);
    assert.equal(record.licenseVersion, '4.0');
    assert.ok(record.attribution && record.attribution.length > 20, `${record.id}: the stated credit is retained`);
    assert.equal(record.rightsEvidenceSource, record.iiifManifest);
  }
  const provider = providerById.get('leventhal');
  assert.equal(provider.rightsPolicy.copyright, 'https://www.digitalcommonwealth.org/copyright');
  assert.match(provider.rightsPolicy.metadataReuse, /does not publish a separate metadata licence/i);
});
  assert.match(wrangler, /"run_worker_first"\s*:\s*\[\s*"\/api\/\*"\s*\]/, 'only /api/* should invoke the Worker');
  assert.match(wrangler, /"compatibility_date"\s*:\s*"\d{4}-\d{2}-\d{2}"/);
  assert.ok(pkg.scripts.dev && pkg.scripts.build && pkg.scripts.test && pkg.scripts['dry-run'], 'documented npm scripts');
  assert.match(pkg.scripts['dry-run'], /wrangler deploy --dry-run/, 'deployment is verified without credentials');
  assert.ok(pkg.devDependencies.wrangler, 'wrangler is pinned in devDependencies');
  assert.ok(pkg.type === 'module');
});

test('the Worker is not an open proxy and holds no credentials', () => {
  const hosts = [...worker.matchAll(/host:\s*'([^']+)'/g)].map((m) => m[1]);
  assert.ok(hosts.length >= 3);
  for (const host of hosts) {
    // The worldwide gazetteer is the one non-Swiss upstream the app talks to;
    // it is admitted for `/search` only (see src/worker/allowlist.js).
    assert.ok(
      /^(api3|wmts|data)\.geo\.admin\.ch$|^www\.e-rara\.ch$|^nominatim\.openstreetmap\.org$|^www\.loc\.gov$|^tile\.loc\.gov$|^(purl|stacks)\.stanford\.edu$|^collections\.leventhalmap\.org$|^iiif\.digitalcommonwealth\.org$|^ark\.digitalcommonwealth\.org$/.test(host),
      `unexpected proxy host ${host}`,
    );
  }
  assert.ok(!/oldmapsonline/i.test(worker), 'no aggregator endpoints');
  for (const secret of ['CLOUDFLARE_API_TOKEN', 'CF_API_TOKEN', 'ACCOUNT_ID', 'API_KEY', 'SECRET']) {
    assert.ok(!worker.includes(secret) && !wrangler.includes(secret), `no ${secret} in the Workers sources`);
  }
});

test('repository ships no credentials or generated deployment state', async () => {
  const ignored = await read('.gitignore');
  for (const entry of ['.dev.vars', '.env', 'node_modules', 'dist', '.wrangler']) {
    assert.ok(ignored.includes(entry), `.gitignore must exclude ${entry}`);
  }
  const tracked = await readdir(root);
  assert.ok(!tracked.includes('.dev.vars'), 'no .dev.vars committed');
});

test('the app is reachable through the documented scripts', () => {
  assert.match(pkg.scripts.dev, /wrangler dev/, 'npm run dev starts the Workers preview');
  assert.match(pkg.scripts.test, /node --test/, 'tests run on the Node test runner without extra deps');
});

test('global atlas branding stays independent of the design reference', async () => {
  assert.match(html, /<title>Meridian Atlas/);
  const header = html.slice(html.indexOf('<header'), html.indexOf('</header>'));
  assert.doesNotMatch(header, /Kartenzeit|Kanton|Zürich|coat.of.arms/i, 'the header identifies the atlas itself');
  const icon = await read('public/favicon.svg');
  assert.match(icon, /<title>Meridian Atlas<\/title>/);
  assert.doesNotMatch(icon, /Kartenzeit|Kanton|Zürich/);
  const headers = await read('public/_headers');
  assert.match(headers, /img-src[^;]+https:\/\/tile\.openstreetmap\.org/);
  assert.match(headers, /img-src[^;]+https:\/\/tile\.loc\.gov/);
  // Doria's provider originals and thumbnails are plain <img> URLs, so CSP must
  // admit that exact host or every Doria preview is blocked in the browser.
  assert.match(headers, /img-src[^;]+https:\/\/www\.doria\.fi/);
  // SLUB publishes direct thumbnail/original JPEGs from its own digitisation
  // server; the CSP must admit that exact host too.
  assert.match(headers, /img-src[^;]+https:\/\/digital\.slub-dresden\.de/);
});

test('provider originals are linked when the collection has no IIIF service', () => {
  const detail = modules['detail.js'];
  // Doria publishes JPEG/PDF bitstreams instead of IIIF. The detail view must
  // expose those real links rather than claiming no image exists.
  assert.equal(res.status, 200);
  const body = await res.json();
  assert.equal(body.ok, true);
  assert.ok(body.upstreams.includes('purl.stanford.edu'));
  assert.ok(body.upstreams.includes('wmts.geo.admin.ch'));
  assert.ok(!body.upstreams.includes('www.oldmapsonline.org'), 'the aggregator is not a data backend');
  assert.deepEqual(body.endpoints, ['/api/health', '/api/records', '/api/layers', '/api/sources', '/api/search/places', '/api/fetch', '/api/raster', '/api/georeference', '/api/catalogue']);
});

test('GET /api/records serves the committed seed data with a cache header', async () => {
  const res = await call('/api/records');
  assert.equal(res.status, 200);
  assert.match(res.headers.get('cache-control'), /max-age=\d+/);
  const body = await res.json();
  assert.ok(Array.isArray(body.records) && body.records.length > 0);
  assert.equal(body.records.length, committed.records.length, 'the route merges every committed shard');
  assert.ok(body.records.some((record) => record.providerId === 'leventhal'), 'a shard provider is present');
  assert.ok(body.generatedAt);
});

test('GET /api/layers and /api/sources serve the registry files', async () => {
  const layers = await (await call('/api/layers')).json();
  assert.ok(Array.isArray(layers.overlays) && layers.overlays.length > 0);
  const sources = await (await call('/api/sources')).json();
  assert.ok(Array.isArray(sources.providers) && sources.providers.length > 0);
});

